output.message:
{
  "steps": [
    {
      "step_id": "cb_step_1",
      "title": "Choose the pelvic CT volume",
      "simple": "In the Input CT Volume selector, choose the Pelvic Volume.",
      "detailed": "This step tells the tool which CT scan to use for the pelvic bone and fracture analysis. Select the volume that contains the patient's pelvis, as all subsequent segmentation and planning will use this imaging data."
    },
    {
      "step_id": "cb_step_2",
      "title": "Segment the pelvis",
      "simple": "Click the 'Run Step 1: Segment Pelvis' button.",
      "detailed": "This creates a 3D model of the whole bony pelvis, which provides the anatomical framework for fracture analysis. The pelvic segmentation will be used to generate the template and guide the reduction of fracture fragments."
    },
    {
      "step_id": "cb_step_3",
      "title": "Segment the fracture fragments",
      "simple": "Click the 'Run Step 2: Segment Fractures' button.",
      "detailed": "This step separates the broken pelvis into individual fracture fragments so each piece can be tracked and repositioned. The resulting fragment map is the basis for manual splitting, reduction, and screw planning."
    },
    {
      "step_id": "cb_step_4",
      "title": "Choose pieces not to keep separate",
      "simple": "In the 'Untick a piece to stop treating it as separate' section, untick the segments that should not be treated as separate pieces.",
      "detailed": "Some small or comminuted pieces may be better handled as part of a larger fragment rather than as independent pieces. Unticking them tells the workflow to merge them with the adjacent bone and not plan reductions around them."
    },
    {
      "step_id": "cb_step_5",
      "title": "Decide if manual separation is needed",
      "simple": "Choose Yes if any fragment was not split cleanly and needs a manual cut; choose No if all fragments are already separated.",
      "detailed": "Automatic fracture segmentation can leave fragments connected by a thin bridge or incomplete split. This decision determines whether you will use the cutting-plane tool to finish the separation before reduction."
    },
    {
      "step_id": "cb_step_6",
      "title": "Start manual separation",
      "simple": "Click the 'Manually separate' button.",
      "detailed": "This activates the cutting-plane tool so you can split a fragment that is still connected to another piece. You will use this after the automatic fracture segmentation when a fracture line needs to be completed by hand."
    },
    {
      "step_id": "cb_step_7",
      "title": "Define the cutting plane",
      "simple": "Click in the scene to place the cut point on the fragment, then adjust the position and rotation of the cutting plane so it follows the desired fracture line.",
      "detailed": "This marks where the connected bone should be split into two separate pieces. Place the plane exactly along the fracture boundary so the separation creates anatomically correct fragments for reduction."
    },
    {
      "step_id": "cb_step_8",
      "title": "Confirm the separation",
      "simple": "Click the 'Confirm separation' button.",
      "detailed": "This tells the tool to apply the cutting plane and split the fragment into separate pieces. Confirming makes the manual split permanent before you proceed to template generation and reduction."
    },
    {
      "step_id": "cb_step_9",
      "title": "Generate the pelvic template",
      "simple": "Click the 'Run Step 3: Generate template' button.",
      "detailed": "This builds a template representing the intact, anatomically correct pelvis that will be used as the target for fracture reduction. The template is created from the pelvic segmentation and later helps bring displaced fragments back into alignment."
    },
    {
      "step_id": "cb_step_10",
      "title": "Decide if the template needs adjustment",
      "simple": "If the generated template needs manual repositioning or rotation, choose Yes; otherwise choose No.",
      "detailed": "The template may not align perfectly with the patient's anatomy, especially in complex fractures. Adjusting it now ensures the reduction target matches the patient's true pelvic shape before fragments are moved."
    },
    {
      "step_id": "cb_step_11",
      "title": "Select the template to adjust",
      "simple": "In the 'Template' selection box, choose the template that needs adjustment.",
      "detailed": "Pick the specific template component you want to reposition or rotate. This allows you to fine-tune each template part individually before applying adjustments."
    },
    {
      "step_id": "cb_step_12",
      "title": "Inspect the template in 3D",
      "simple": "Rotate, zoom, and pan the 3D view to get a clear view of the selected template.",
      "detailed": "Use the mouse to change your viewpoint only; no clicking or marking is needed in this step. A clear view helps you judge how the template sits relative to the patient's pelvis before any manual adjustments."
    },
    {
      "step_id": "cb_step_13",
      "title": "More templates to adjust?",
      "simple": "If another template also needs adjustment, choose Yes; otherwise choose No.",
      "detailed": "This lets you loop through all templates that require fine-tuning. Continue until each template is correctly aligned before applying the final adjustments."
    },
    {
      "step_id": "cb_step_14",
      "title": "Apply the template adjustments",
      "simple": "Click the 'Apply template adjustment' button.",
      "detailed": "This commits all the template position and rotation changes you made. Applying them updates the reduction target used in the next registration and reduction step."
    },
    {
      "step_id": "cb_step_15",
      "title": "Register and reduce the fracture",
      "simple": "Click the 'Run Step 4: Register _Reduce' button.",
      "detailed": "This aligns the fracture fragments with the pelvic template and moves them into their correct anatomical positions, simulating fracture reduction. The output is a reduced pelvic model that can be further refined manually and used for screw planning."
    },
    {
      "step_id": "cb_step_16",
      "title": "Decide if fragment adjustments are needed",
      "simple": "If any fragment still needs manual repositioning or rotation after reduction, choose Yes; otherwise choose No.",
      "detailed": "Automatic reduction may leave small residual displacements or rotational errors. This decision determines whether you will manually fine-tune individual fragments before planning screws."
    },
    {
      "step_id": "cb_step_17",
      "title": "Select the fragment to adjust",
      "simple": "In the 'Fragment' selection box, choose the fragment that needs adjustment.",
      "detailed": "Pick the individual fracture fragment you want to refine. This lets you work on one bone piece at a time so its final position matches the uninjured pelvic anatomy."
    },
    {
      "step_id": "cb_step_18",
      "title": "Inspect the fragment in 3D",
      "simple": "Rotate, zoom, and pan the 3D view to get a clear view of the selected fragment.",
      "detailed": "Use the mouse to change your viewpoint only; no clicking or marking is needed in this step. Seeing the fragment from multiple angles helps you judge whether its position and rotation are correct."
    },
    {
      "step_id": "cb_step_19",
      "title": "More fragments to adjust?",
      "simple": "If another fragment also needs adjustment, choose Yes; otherwise choose No.",
      "detailed": "This lets you refine each displaced fragment until the whole pelvic ring is well reduced. Once all fragments are aligned, you can apply the adjustments and move on to screw planning."
    },
    {
      "step_id": "cb_step_20",
      "title": "Apply the fragment adjustments",
      "simple": "Click the 'Apply adjustments' button.",
      "detailed": "This saves the manual position and rotation changes you made to the fracture fragments. The updated reduced pelvis will be used for the next planning steps."
    },
    {
      "step_id": "cb_step_21",
      "title": "Plan screw trajectories",
      "simple": "Click the 'Run Step 5: Plan Screws' button.",
      "detailed": "This automatically suggests screw trajectories for stabilizing the reduced pelvis. The planned screws will be checked and can be edited to ensure safe fixation paths."
    },
    {
      "step_id": "cb_step_22",
      "title": "Decide if screw trajectories need editing",
      "simple": "If you want to adjust the planned screw paths, choose Yes; otherwise the planning workflow is complete.",
      "detailed": "Screw plans may need refinement to stay within safe bone corridors and avoid joints or important structures. Choosing Yes lets you edit and regenerate the screw trajectories."
    },
    {
      "step_id": "cb_step_23",
      "title": "Inspect the screw trajectories in 3D",
      "simple": "Rotate, zoom, and pan the 3D view to get a clear view of the planned screw trajectories.",
      "detailed": "Use the mouse to change your viewpoint only; no clicking or marking is needed in this step. This helps you verify that each screw path lies safely inside bone before regeneration."
    },
    {
      "step_id": "cb_step_24",
      "title": "Regenerate the edited screws",
      "simple": "Click the 'Regenerate screws from edited lines' button.",
      "detailed": "This rebuilds the screw models from the edited trajectory lines so the fixation plan reflects your adjustments. The regenerated screws provide the final planned implant positions for the case."
    }
  ]
}
